import { pipeline, env } from '@huggingface/transformers';
import { mkdir, writeFile, readFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import os from 'node:os';
import { loadDataset, validateDataset, readJSON, hash } from '../lib/data.js';
import { validateConfig } from '../lib/config.js';
import { textFor, rankFolders, evaluate, summarize } from '../lib/scoring.js';

const config=validateConfig(await readJSON(process.argv[2]??'benchmark.config.json'));
const datasets=await Promise.all(config.datasets.map(name=>loadDataset(name)));
const validation=datasets.map(validateDataset);
console.table(validation);
const runId=`${new Date().toISOString().replace(/[:.]/g,'-')}-${randomUUID().slice(0,8)}`;
const dir=`results/${runId}`;
await mkdir(dir,{recursive:true});
env.cacheDir=config.cacheDir;
const sourceFiles=['scripts/bench.js','lib/data.js','lib/config.js','lib/scoring.js'];
const sourceSnapshot=Object.fromEntries(await Promise.all(sourceFiles.map(async file=>[file,await readFile(file,'utf8')])));
const run={schemaVersion:1,runId,createdAt:new Date().toISOString(),status:'running',config,validation,datasets,
  sourceHash:hash(sourceSnapshot),sourceSnapshot,
  environment:{node:process.version,transformers:'4.3.2',platform:process.platform,arch:process.arch,cpu:os.cpus()[0]?.model},
  timing:'Sequential CPU calls after warmup. Each input is embedded once per model and shared across strategies. queryMs = embeddingMs + rankingMs; excludes load/index/report. No query cache. One timing sample per case.',
  results:[]};
const save=()=>writeFile(`${dir}/run.json`,JSON.stringify(run,null,2)+'\n');
await writeFile(`${dir}/config.json`,JSON.stringify(config,null,2)+'\n');
await save();
try {
  for(const model of config.models){
    console.log(`Loading ${model.id} (${model.dtype}, CPU)…`);
    const loadStart=performance.now();
    const extractor=await pipeline('feature-extraction',model.model,{dtype:model.dtype,device:'cpu',local_files_only:config.localFilesOnly});
    const loadMs=performance.now()-loadStart;
    try {
      const embed=async text=>{
        const v=(await extractor(text,{pooling:model.pooling,normalize:true,truncation:true,max_length:model.maxLength})).tolist()[0];
        if(!v.length||!v.every(Number.isFinite))throw new Error('Invalid embedding');
        return v;
      };
      await embed('Warm up. Rozgrzewka.');
      for(const dataset of datasets){
        const startIndex=performance.now(),indices=new Map();
        for(const collection of dataset.collections){
          const folders=[];
          for(const folder of collection.folders){
            const examples=[];
            for(const e of dataset.index.filter(e=>e.collectionId===collection.id&&e.folder===folder.path))examples.push(await embed(textFor(e,config.indexFields)));
            folders.push({path:folder.path,vector:await embed(textFor(folder,config.folderFields)),examples});
          }
          indices.set(collection.id,folders);
        }
        const indexMs=performance.now()-startIndex;
        for(const input of config.inputs){
          const outputs=config.strategies.map(strategy=>({id:`${model.id}/${strategy.id}/${input.id}`,dataset:dataset.name,model,input,strategy,loadMs,indexMs,rows:[]}));
          for(const [idx,item] of dataset.evaluation.entries()){
            const queryText=textFor(item,input.fields),start=performance.now(),vector=await embed(queryText),embeddingMs=performance.now()-start;
            for(const output of outputs){
              const scoreStart=performance.now(),ranked=rankFolders(vector,indices.get(item.collectionId),output.strategy),rankingMs=performance.now()-scoreStart;
              output.rows.push({...item,queryText,...evaluate(ranked,item,config.thresholds),embeddingMs,rankingMs,queryMs:embeddingMs+rankingMs});
            }
            if((idx+1)%30===0)console.log(`${model.id} / ${dataset.name} / ${input.id}: ${idx+1}/${dataset.evaluation.length}`);
          }
          for(const output of outputs){output.metrics=summarize(output.rows);run.results.push(output);console.log(`${output.id} ${dataset.name}: accuracy ${(100*output.metrics.accuracy).toFixed(1)}%, top-3 ${(100*output.metrics.top3Coverage).toFixed(1)}%`);}
          await save();
        }
      }
    }finally{await extractor.dispose();}
  }
  run.status='complete';run.completedAt=new Date().toISOString();await save();
}catch(error){run.status='failed';run.error=error.stack;await save();throw error;}
console.log(`Saved ${dir}/run.json`);
if(config.report){const {createReport}=await import('./report.js');await createReport(`${dir}/run.json`);}

