export function validateConfig(c) {
  const assert=(ok,message)=>{if(!ok)throw new Error(`Configuration: ${message}`);};
  const uniqueIds=(items,key='id')=>Array.isArray(items)&&items.length&&items.every(x=>typeof x[key]==='string'&&x[key].length)&&new Set(items.map(x=>x[key])).size===items.length;
  assert(Array.isArray(c.datasets)&&c.datasets.length&&c.datasets.every(d=>['synthetic','real'].includes(d))&&new Set(c.datasets).size===c.datasets.length,'invalid datasets');
  for(const key of ['models','strategies','inputs'])assert(uniqueIds(c[key]),`unique nonempty ${key} IDs required`);
  const fields=(xs,allowed)=>Array.isArray(xs)&&xs.length&&xs.every(x=>allowed.includes(x))&&new Set(xs).size===xs.length;
  for(const m of c.models)assert(m.model&&m.dtype==='q8'&&['mean','cls'].includes(m.pooling)&&Number.isInteger(m.maxLength)&&m.maxLength>0,'invalid model');
  for(const s of c.strategies)assert(['closest','weighted'].includes(s.type)&&(s.type==='closest'||Number.isFinite(s.folderWeight)&&s.folderWeight>=0&&s.folderWeight<=1),'invalid strategy/weight');
  for(const i of c.inputs)assert(fields(i.fields,['title','description','headings','url']),'invalid input fields');
  assert(fields(c.indexFields,['title','description','headings','url']),'invalid index fields');
  assert(fields(c.folderFields,['path','description']),'invalid folder fields');
  assert(Number.isFinite(c.thresholds?.newFolder)&&c.thresholds.newFolder>=-1&&c.thresholds.newFolder<=1&&Number.isFinite(c.thresholds.askUserMargin)&&c.thresholds.askUserMargin>=0,'invalid thresholds');
  assert(c.models.some(m=>c.strategies.some(s=>c.inputs.some(i=>`${m.id}/${s.id}/${i.id}`===c.baseline))),'baseline must name an enabled configuration');
  assert(typeof c.cacheDir==='string'&&typeof c.localFilesOnly==='boolean'&&typeof c.report==='boolean','cacheDir, localFilesOnly and report required');
  return c;
}

