export const textFor = (item, fields) => fields.flatMap(field => item[field] ?? []).filter(Boolean).join('. ');
export const dot = (a,b) => a.reduce((sum,value,i)=>sum+value*b[i],0);
export function rankFolders(vector, folders, strategy) {
  return folders.map(folder => {
    const bookmarkScore = Math.max(...folder.examples.map(example=>dot(vector,example)));
    const folderScore = dot(vector,folder.vector);
    return { folder:folder.path, score:strategy.type==='closest' ? bookmarkScore : strategy.folderWeight*folderScore+(1-strategy.folderWeight)*bookmarkScore,
      bookmarkScore, folderScore };
  }).sort((a,b)=>b.score-a.score || a.folder.localeCompare(b.folder,'en'));
}
export function evaluate(ranked, item, thresholds) {
  const topFolder=ranked[0].folder, margin=ranked[0].score-ranked[1].score;
  const decision=ranked[0].score<thresholds.newFolder ? 'new-folder' : margin<thresholds.askUserMargin ? 'ask-user' : 'assign';
  const predicted=decision==='new-folder' ? null : topFolder;
  const expectedRank=item.expectedFolder===null ? null : ranked.findIndex(r=>r.folder===item.expectedFolder)+1;
  return {topFolder, predicted, decision, margin, expectedRank,
    correct:predicted===item.expectedFolder, top1Correct:topFolder===item.expectedFolder,
    top3Covered:item.expectedFolder===null ? null : expectedRank>0 && expectedRank<=3,
    top3:ranked.slice(0,3), ranked};
}
const ratio=(n,d)=>d ? n/d : null;
export function summarize(rows) {
  const eligible=rows.filter(r=>r.expectedFolder!==null), sorted=rows.map(r=>r.queryMs).sort((a,b)=>a-b);
  const unique=[...new Map(rows.map(r=>[`${r.collectionId}:${r.duplicateGroup}`,r])).values()];
  const clear=rows.filter(r=>!r.ambiguous);
  const assigned=rows.filter(r=>r.decision==='assign');
  return { count:rows.length, correct:rows.filter(r=>r.correct).length, accuracy:ratio(rows.filter(r=>r.correct).length,rows.length),
    top1Accuracy:ratio(eligible.filter(r=>r.top1Correct).length,eligible.length),
    top3Count:eligible.filter(r=>r.top3Covered).length, top3Denominator:eligible.length,
    top3Coverage:ratio(eligible.filter(r=>r.top3Covered).length,eligible.length),
    unambiguousAccuracy:ratio(clear.filter(r=>r.correct).length,clear.length), unambiguousCount:clear.length,
    uniqueAccuracy:ratio(unique.filter(r=>r.correct).length,unique.length), uniqueCount:unique.length,
    autoAssigned:assigned.length, autoAccuracy:ratio(assigned.filter(r=>r.correct).length,assigned.length),
    meanQueryMs:ratio(sorted.reduce((a,b)=>a+b,0),sorted.length), p50QueryMs:sorted[Math.ceil(sorted.length*.5)-1],p95QueryMs:sorted[Math.ceil(sorted.length*.95)-1] };
}
export function changeStatus(baseline, current) {
  return baseline ? (current ? 'Still correct' : 'Regressed') : (current ? 'Fixed' : 'Still wrong');
}
